#include "osls.h"
#include <assert.h>
int main(void){osls_system_info i;osls_process_info p;osls_file_info f;osls_cpu_info c;osls_timezone_info z;size_t n=0,w=0;char env[1024],names[8192];int64_t next=0;assert(osls_get_system_info(&i)==OSLS_OK&&i.process_id);assert(osls_get_process_info(0,&p)==OSLS_OK&&p.pid);assert(osls_enumerate_processes(&p,1,&n)==OSLS_OK&&n==1);assert(osls_get_environment_value("PATH",env,sizeof(env))==OSLS_OK);assert(osls_get_file_info(".",&f)==OSLS_OK&&f.is_directory);assert(osls_list_directory(".",names,sizeof(names),&w)==OSLS_OK&&w);assert(osls_get_cpu_info(&c)==OSLS_OK&&c.logical_cores);assert(osls_get_timezone_info(&z)==OSLS_OK);assert(osls_cron_validate("*/15 9-17 * * 1-5")==OSLS_OK);assert(osls_cron_validate("60 * * * *")==OSLS_INVALID_ARGUMENT);assert(osls_cron_next_after("0 0 * * *",1704067200,&next)==OSLS_OK&&next>1704067200);return 0;}
